def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining >= 0, - (remaining % item), -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    max_count = bins // item
    leftover = bins % item
    return np.where(bins >= item, -(max_count * leftover), -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
